import 'package:flutter/material.dart'; import '../models/certificate_model.dart'; class CertificateCard extends StatelessWidget { final CertificateModel certificate; final VoidCallback? onTap; const CertificateCard({super.key,required this.certificate,this.onTap}); @override Widget build(BuildContext c)=>Card(child:ListTile(onTap:onTap,leading:const Icon(Icons.workspace_premium),title:Text(certificate.courseName),subtitle:Text('رقم الشهادة: ${certificate.certificateNumber}'),trailing:Text('${certificate.score.toStringAsFixed(0)}%'))); }